import { describe, it, expect } from 'vitest';
import { parseColumnLine, sqlTypeToTs } from '@/scripts/gen-db-types.mjs';

/**
 * R03-006 — Il generatore dei tipi scriveva le colonne array (text[], uuid[]) come `string`
 * invece di `string[]`. Si esegue la vera funzione che legge ogni riga di colonna.
 */
describe('R03-006 — le colonne array nei tipi generati', () => {
  it.each([
    ['tags text[]', 'string[]'],
    ['rider_zones text[] NOT NULL DEFAULT \'{}\'', 'string[]'],
    ['photo_urls text[] DEFAULT ARRAY[]::text[]', 'string[]'],
    ['product_ids uuid[]', 'string[]'],
    ['percorsi text[] NOT NULL', 'string[]'],
    ['voti integer[]', 'number[]'],
    ['dati jsonb[]', 'Json[]'],
  ])('%s → %s', (riga, atteso) => {
    expect(parseColumnLine(riga)?.tsType).toBe(atteso);
  });

  it('le colonne normali restano quelle di prima', () => {
    expect(parseColumnLine('nome text NOT NULL')).toMatchObject({ tsType: 'string', nullable: false });
    expect(parseColumnLine('id uuid PRIMARY KEY')?.tsType).toBe('string');
    expect(parseColumnLine('prezzo numeric(10, 2) NOT NULL')?.tsType).toBe('number');
  });

  it('il nome interno degli array di Postgres (_text) non manda la funzione in ricorsione', () => {
    expect(sqlTypeToTs('_text')).toBe('string[]');
    expect(sqlTypeToTs('uuid[]')).toBe('string[]');
  });
});
